// SCORE COMPOSTO (max 100 pontos)
const o = $input.item.json;
const now = new Date();
const coletado = new Date(o.coletado_em);
const minAge = (now - coletado) / (1000 * 60);

let score = 0;
const breakdown = {};

// 1) DESCONTO REAL (via Zoom validator) — max 40 pontos
if (o.veredicto_zoom === 'oferta_real') {
  score += 40;
  breakdown.desconto_real = 40;
} else if (o.veredicto_zoom === 'preco_medio') {
  score += 15;
  breakdown.desconto_real = 15;
} else if (o.desconto_pct >= 30) {
  score += 25;
  breakdown.desconto_declarado = 25;
} else if (o.desconto_pct >= 20) {
  score += 15;
  breakdown.desconto_declarado = 15;
} else if (o.desconto_pct >= 10) {
  score += 5;
  breakdown.desconto_declarado = 5;
}

// 2) FONTE CONFIÁVEL — max 15 pontos
const fontesTop = ['meliuz-oferta', 'meliuz-cupom', 'mercadolivre', 'amazon'];
const fontesMedias = ['shopee', 'aliexpress', 'telegram-ligadaoferta'];
if (fontesTop.some(f => (o.fonte || '').includes(f))) {
  score += 15; breakdown.fonte = 15;
} else if (fontesMedias.some(f => (o.fonte || '').includes(f))) {
  score += 10; breakdown.fonte = 10;
} else {
  score += 5; breakdown.fonte = 5;
}

// 3) FRESHNESS — max 15 pontos (recentíssimo = mais chance de ainda ter estoque)
if (minAge < 15) { score += 15; breakdown.freshness = 15; }
else if (minAge < 60) { score += 10; breakdown.freshness = 10; }
else if (minAge < 120) { score += 5; breakdown.freshness = 5; }

// 4) COMISSÃO — max 10 pontos
const com = parseFloat(o.comissao_pct || 0);
if (com >= 12) { score += 10; breakdown.comissao = 10; }
else if (com >= 8) { score += 7; breakdown.comissao = 7; }
else if (com >= 5) { score += 4; breakdown.comissao = 4; }

// 5) URGÊNCIA (categoria flash-sale, super-deal, etc) — max 10 pontos
const cat = (o.categoria || '').toLowerCase();
if (cat.includes('flash') || cat.includes('relampago') || cat.includes('super-deal')) {
  score += 10; breakdown.urgencia = 10;
}

// 7) FEEDBACK LOOP (workflow 15) — boost -10 a +20 baseado em CTR historico da categoria
const boostCat = parseInt(o.boost_categoria || 0);
score += boostCat;
if (boostCat !== 0) breakdown.boost_feedback = boostCat;

// 6) TRENDING NOW (dinamico via tabela termos_hot_agora) — max 10 pontos
// Fonte: workflow 14 (Google Trends BR + ML Trends) atualiza tabela a cada 1h
const termosHotMatch = o.termos_hot_match || [];
if (termosHotMatch.length >= 2) {
  score += 10; breakdown.trending_now = 10;
  breakdown.termos_matched = termosHotMatch;
} else if (termosHotMatch.length === 1) {
  score += 7; breakdown.trending_now = 7;
  breakdown.termos_matched = termosHotMatch;
} else {
  // Fallback: lista fixa se workflow 14 nao esta rodando
  const titulo = (o.titulo || '').toLowerCase();
  const keywordsHot = ['iphone', 'samsung', 'notebook', 'smart tv', 'kindle', 'air fryer', 'echo dot', 'ps5', 'xbox'];
  if (keywordsHot.some(k => titulo.includes(k))) {
    score += 5; breakdown.categoria_fallback = 5;
  }
}

return {
  json: {
    id: o.id,
    score_total: Math.min(score, 100),
    breakdown_json: JSON.stringify(breakdown)
  }
};
